
import io
import os
import numpy as np
import streamlit as st
import torch
from PIL import Image
from model import ConvVAE

MODEL_PATH = "checkpoints/vae_cifar10.pt"
IMAGE_SIZE = 64

st.set_page_config(
    page_title="Image Denoising & Comparison Lab",
    page_icon="🖼️",
    layout="wide"
)

st.title("Image Denoising and Comparison Lab")
st.write(
    "Upload an image, add Gaussian noise, compress it into a latent "
    "representation, and reconstruct it using a trained VAE."
)

st.info(
    "The image is resized to 64×64 RGB for processing. "
    "The reconstructed image is generated by the VAE decoder."
)

@st.cache_resource
def load_model(path, mtime):
    checkpoint = torch.load(
        path,
        map_location="cpu",
        weights_only=False
    )
    model = ConvVAE(checkpoint.get("latent_dim", 128))
    model.load_state_dict(checkpoint["model_state_dict"])
    model.eval()
    return model

if not os.path.exists(MODEL_PATH):
    st.error(
        "Trained model not found. Run `python train_local.py` "
        "from the project folder first."
    )
    st.stop()

try:
    model = load_model(MODEL_PATH, os.path.getmtime(MODEL_PATH))
except Exception as exc:
    st.error(f"Could not load the trained model: {exc}")
    st.stop()

with st.sidebar:
    st.header("Compression and noise settings")

    uploaded = st.file_uploader(
        "Upload an image",
        type=["png", "jpg", "jpeg", "jfif"]
    )

    noise_level = st.slider(
        "Gaussian noise level",
        min_value=0,
        max_value=100,
        value=25,
        step=5
    )

    latent_dim = st.selectbox(
        "Latent dimension",
        options=[32, 64, 128],
        index=2
    )

    st.caption(
        f"Loaded checkpoint latent dimension: {model.latent_dim}"
    )

if latent_dim != model.latent_dim:
    st.warning(
        f"This model uses latent dimension {model.latent_dim}. "
        "Select that dimension to continue."
    )
    st.stop()


def image_to_tensor(pil_image):
    arr = np.asarray(
        pil_image.resize((IMAGE_SIZE, IMAGE_SIZE)),
        dtype=np.float32
    ) / 255.0

    return torch.from_numpy(arr).permute(2, 0, 1).unsqueeze(0)


def tensor_to_image(tensor):
    arr = (
        tensor.detach()
        .cpu()
        .squeeze(0)
        .clamp(0, 1)
        .permute(1, 2, 0)
        .numpy()
    )

    return Image.fromarray(
        (arr * 255).round().astype(np.uint8)
    )


def mse(a, b):
    aa = np.asarray(a, dtype=np.float32) / 255.0
    bb = np.asarray(b, dtype=np.float32) / 255.0
    return float(np.mean((aa - bb) ** 2))


def psnr(mse_value):
    if mse_value <= 0:
        return float("inf")
    return 10.0 * np.log10(1.0 / mse_value)


if uploaded is None:
    st.subheader("How it works")
    st.markdown(
        "1. Upload an image.\n"
        "2. Select a noise level.\n"
        "3. Run the VAE encoder and decoder.\n"
        "4. Compare images and reconstruction metrics."
    )
    st.stop()

try:
    original_pil = Image.open(
        io.BytesIO(uploaded.getvalue())
    ).convert("RGB")
except Exception as exc:
    st.error(f"Unable to read the uploaded image: {exc}")
    st.stop()

st.image(
    original_pil,
    caption=f"Original upload — {original_pil.width}×{original_pil.height}",
    width=400
)

if st.button("Run comparison", type="primary"):
    x = image_to_tensor(original_pil)

    # Repeatable noise makes comparisons easier.
    generator = torch.Generator(device="cpu").manual_seed(7)
    sigma = (noise_level / 100.0) * 0.35

    noise = torch.randn(
        x.shape,
        generator=generator,
        dtype=x.dtype
    )

    noisy = (x + noise * sigma).clamp(0, 1)

    with torch.no_grad():
        # Real encoder -> latent mean -> decoder.
        mu, logvar = model.encode(noisy)
        z = mu
        reconstruction = model.decode(z).clamp(0, 1)

    original_64 = tensor_to_image(x)
    noisy_pil = tensor_to_image(noisy)
    recon_pil = tensor_to_image(reconstruction)

    st.subheader("Image comparison")

    c1, c2, c3 = st.columns(3)

    c1.image(
        original_64,
        caption="Original (64×64 model input)",
        use_container_width=True
    )
    c2.image(
        noisy_pil,
        caption=f"Noisy image ({noise_level}%)",
        use_container_width=True
    )
    c3.image(
        recon_pil,
        caption="VAE reconstruction",
        use_container_width=True
    )

    original_mse = mse(original_64, recon_pil)
    noisy_mse = mse(original_64, noisy_pil)
    reconstruction_psnr = psnr(original_mse)

    st.subheader("Reconstruction metrics")

    col1, col2, col3, col4 = st.columns(4)

    col1.metric("Latent vector", f"{z.shape[1]} values")
    col2.metric("Noisy vs original MSE", f"{noisy_mse:.6f}")
    col3.metric("Reconstruction vs original MSE", f"{original_mse:.6f}")
    col4.metric(
        "Reconstruction PSNR",
        "∞" if np.isinf(reconstruction_psnr)
        else f"{reconstruction_psnr:.2f} dB"
    )

    if original_mse < noisy_mse:
        st.success(
            "The reconstruction has lower MSE than the noisy input "
            "for this image."
        )
    else:
        st.warning(
            "The reconstruction MSE is not lower than the noisy input. "
            "The current model has not demonstrated successful denoising "
            "for this image."
        )

    st.caption(
        "MSE is calculated in normalized [0,1] pixel space against "
        "the original 64×64 model input. Lower MSE and higher PSNR "
        "indicate a closer pixel-level reconstruction."
    )

    st.subheader("Download reconstruction")

    buffer = io.BytesIO()
    recon_pil.save(buffer, format="PNG")

    st.download_button(
        "Download reconstructed PNG",
        data=buffer.getvalue(),
        file_name="vae_reconstruction.png",
        mime="image/png"
    )
